  g = `Vælg en eller flere pakker nedenfor, og klik "Fortsæt" for at tilføje dem til dette bundt.`,
  _ = `Samarbejde om bundt`,
  v = `Valgfrit: Du kan vælge at invitere andre udviklere til at inkludere deres spil i dit bundt. Som ejer af bundtet er du ansvarlig for at koordinere med de andre udviklere. Som ejer er du også den eneste, som kan udgive bundtet i Steam-butikken. De inviterede parter kan vælge, hvilke spil/pakker de vil inkludere. Hver gang pakker tilføjes til bundtet, eller rabatprocenten ændres, skal alle parter godkende, at deres spil inkluderes i bundtet, før det kan udgives.`,
