  w = `Dashboard til udsalgssider`,
  T = `Begivenhedssider for udsalgskampagner`,
  E = `Her finder du udsalgssiderne på Steam, som indeholder et eller flere spil, som du har administratorrettigheder til. Nogle gange er siderne tilrettelagt af begivenhedsarrangører og nogle gange af Valve som en del af en kampagne.`,
  D = `Dette er alle de aktive og klargjorte udsalgssider oprettet af enten Valve eller en godkendt ekstern gruppe. %1$s for at opsætte en ny partner, som kan oprette sin egen udsalgsside. Du kan videresende %2$s til din partner.`,
