  j = `Aktive udsalg: %1$s`,
  M = `Sider for kommende sæsonudsalg: %1$s`,
  N = `Dette er udsalgssider, som vi planlægger at have med på startsiden på Steam under det næste store sæsonudsalg (hvis der er rabat på de inkluderede spil). Kontrollér, at disse inkluderer alle relevante spil i din franchise.`,
  P = `Links`,
  F = `Udgivne kommende udsalg: %1$s`,
