  H = `Udsalg varer til`,
  U = `Inkluderede spil (hurtig visning)`,
  W = `Dette er listen over jeres spil, som er med i begivenheden.`,
  G = `Gennemse`,
  K = `Denne begivenhed er skjult, og du har ikke redigeringsadgang, men nogen på dit team har. Hold musen over gruppeikonet nedenfor, og klik på "Se medlemsliste" for at finde ud af, hvem på dit team der har tilladelse til at redigere begivenheden. Som standard har medlemmer med officerstatus i gruppen redigeringsrettigheder til denne begivenhed.`,
  q = `Denne begivenhed er ikke synlig endnu, men vi viser den for jer, fordi I har et spil, som er opført på udsalgssiden. Kontakt arrangørerne af udsalget, hvis dette er uventet.`,
