  it = `Udsalg uden en pæn URL vil ikke være synlige i butikken som en udsalgsside og kan ikke fremvises på udsalgssiden, da det alt sammen er URL-baseret.`,
  at = `Opret ny udsalgsbegivenhed`,
  ot = `Vælg en passende fællesskabsgruppe, som begivenheden og udsalget skal oprettes under`,
  st = `Indtast gruppenavn eller butiks-URL`,
  ct = `Udsalgssiden skal oprettes på en skaberside (også kaldet udvikler-/udgiver-/franchiseside). Søg efter navnet på skabersiden nedenfor:`,
  lt = `Indtast navnet på gruppen, som er tilknyttet en skaberside, eller indtast butiks-URL'en, hvis dette er til en kurator eller en ny fællesskabsgruppe.`,
  ut = `1. Valgt skaber til at afholde udsalgsbegivenheden:`,
  dt = `Fjern skaberen, og søg igen efter en anden skaberside`,
  ft = `2. Bekræft, at partnerbegivenheder er slået til på skabersiden:`,
  pt = `Denne skaberside skal tilmeldes partnerbegivenhedsbetaen for at bruge udsalgssektionen. Denne handling kan ikke fortrydes. Det ændrer editoren, når skaberen slår meddelelser op og forhindrer oprettelse af sammenkædede meddelelser. %1$s`,
