  D_ = `Antisnyd`,
  O_ = `Hvis dit spil installerer antisnydesoftware på kerneniveau på klientsiden, skal du oplyse det til brugerne her. Hvis du har din egen løsning til antisnyd, eller hvis løsningen ikke står på listen nedenfor, skal du vælge "andet" og indtaste din egne oplysninger.`,
  k_ = `Hvis dit spil indeholder klient- eller serverbaseret antisnydesoftware, som ikke er kernebaseret, er feltet valgfrit, men vi mener generelt, at det vil gavne alle spil, som bruger antisnydeteknologi, at fortælle spillerne om det.`,
