  iv = `Gruppeudgaver`,
  av = `Forklaring af udgaver...`,
  ov = `I denne grænseflade kan du vælge et billede, som beskriver forskellen mellem udgaverne af dit spil (f.eks. standard vs. deluxe vs. årets spil osv.). Udgaverne grupperes med grundspillet øverst i købsmulighederne og sorteres fra laveste til højeste pris på butikssiden. Se dokumentationen <1>Forklaring af udgaver</1> for mere information.`,
