  mb = `Udelad spilnavnet i starten af genstande på listen over indhold i pakken.`,
  hb = `For at reducere overflødige ord og øge læsbarheden kan du udelade spilnavnet plus blanktegn og bindetegn såsom koloner og bindestreger i starten af genstande som DLC og soundtracks, når de anføres i købsområdet for pakken. For eksempel vises "Half Life 2: Episode 1" som "'Episode 1". Det er kun grundspillets nøjagtige navn plus blanktegn og almindelige skilletegn som bindestreger og koloner, der skjules.`,
