  Db = `Bemærkninger`,
  Ob = `Husk: Det er ikke muligt at indsende en rabat indenfor 30 dage af udgivelse af et spil for første gang til fuld pris eller en prisstigning (uanset valuta). Fuldstændige oplysninger kan findes i %1$s.`,
