  Lb = `Importer/eksporter CSV...`,
  Rb = `Rabatter på dine spilpakker kan også administreres ved at redigere i en .csv-fil. Det kan være brugbart, hvis du har brug for at opdatere mange rabatter på én gang, eller hvis du skal tjekke for overensstemmelse i et stort spilkatalog.`,
