  eR = `Intet valgt. Butikken vælger som standard den første franchiseside, som er tilknyttet dette spil (om nogen).`,
  tR = `<Inkluder fra alle kilder>`,
  nR = `Inkluder alle spil fra alle skabersiderne (udvikler/udgiver/franchise), som er tilknyttet dette spil. Manuel fremhævning gør det muligt at vælge en specifik skaberside, som skal fremhæves. Algoritmisk fremhævning favoriserer den første matchende skaber i rækkefølgen franchise, udvikler, udgiver til fremhævning.`,
  rR = `DLC-afhængigheder`,
  iR = `Kræver dette DLC et andet stykke DLC for at fungere? Vælg de nødvendige stykker DLC, som skal vises som påkrævede. Butikken viser automatisk denne afhængighed sammen med en mulighed for at købe alle afhængige emner sammen.`,
  aR = `Tilføj som afhængighed`,
  oR = `Forhold til afhængigheden`,
  sR = `Påkrævet`,
  cR = `DLC, som er nødvendigt for, at dette DLC kan fungere korrekt.`,
  lR = `Anbefalet`,
  uR = `DLC, som anbefales for at få den bedste oplevelse af dette DLC.`,
  dR = `Oversigt`,
  fR = `Design`,
  pR = `Udgivelse`,
  mR = `Beskrivelse af roadmap for sæsonpas`,
  hR = `Sæsonpas er DLC, som kan købes med et løfte om fremtidigt indhold til kunderne, enten som separate DLC-udgivelser eller som yderligere indhold, der kan låses op i grundspillet.`,
  gR = `Hvis udviklere vil påtage sig denne forpligtelse, skal de beskrive hver af de vigtige datoer for levering af indhold og selve indholdet for spillere ved at indtaste hver dato og indhold nedenfor.`,
  _R = `Brug den generelle sektion "Om dette indhold" ovenfor til at beskrive sæsonpasset generelt og leveringsdatoerne nedenfor til specifikke, individuelle indholdsudgivelser.`,
  vR = `Når du er klar til at fortælle spillere, at du har udgivet indholdet i sæsonpasset, skal du bruge muligheden "Markér som udgivet" nedenfor og følge instruktionerne. Læs <1>dokumentationen om udgivelse for sæsonpas</1> for nærmere oplysninger.`,
  yR = `Opret ny indholdsudgivelse`,
  bR = `Indholdsudgivelse er noget specifikt, som leveres, og som kunder vil forstå, med en forventet leveringsdato.`,
  xR = `Opret ny indholdsudgivelse`,
  SR = `Beskriv indholdsudgivelsen til sæsonpasset for spillere.`,
  CR = `Intern beskrivelse: Fortæl Valve, hvad du agter at inkludere i denne milepæl`,
