  TR = `Titel, som vises for kunder`,
  ER = `Datovisning`,
  DR = `Planlagt udgivelsesdato`,
  OR = `Dette er den dato, du har til hensigt at udgive indholdet til spillere. Datoen bruges til påmindelser på det interne Steamworks-dashboard. Brug lokal tidszone.`,
  kR = `Udgivelsesdato`,
  AR = `Hvornår fik kunder først adgang til dette indhold`,
  jR = `Markér som tidligere udgivet`,
  MR = `Dette er indhold, som er blevet udgivet tidligere. Hvis dette vælges, kan der angives en dato i fortiden. Når dette udgives, får kunder ikke besked om udgivelsen. Valget kan ikke fjernes, hvis datoen er i fortiden.`,
  NR = `Kan ikke fjerne markering som tidligere udgivet uden først at flytte udgivelsesdatoen til fremtiden.`,
  PR = `Kræver, at du gemmer og udgiver`,
  FR = `Datoen skal være i fortiden, fordi indholdet allerede burde være udgivet.`,
