  WR = `Offentlig udgivelsesdato`,
  GR = `Du kan vælge at vise en mindre præcis dato for spillere, hvis du ikke er sikker på den nøjagtige udgivelsesdato for indholdet.`,
  KR = `Titel på indholdsudgivelse (offentlig)`,
  qR = `Hvad hedder dette indhold?`,
  JR = `Beskrivelse af indholdsudgivelse (offentlig)`,
  YR = `Fortæl spillere om indholdet i udgivelsen her. Teksten kan være så lang eller så kort, som du ønsker. Hvis du planlægger at udgive indholdet som DLC, kan beskrivelsen her være den samme som på DLC-siden.`,
