  iz = `Er dette indhold tilgængeligt for spillere?`,
  az = `Indholdet er markeret som tidligere udgivet. Valgfrit: Oplys, hvordan indholdet allerede er tilgængeligt for spillere.`,
  oz = `Hvordan leveres dette indhold?`,
  sz = `Som en opdatering til spillet – nyt indhold er inkluderet i grundspillet eller i form af skjult DLC.`,
