  hz = `Liste over synligt DLC i butikken, som er tilknyttet grundspillet, og som ikke er sæsonpasset og ikke allerede er tilknyttet en anden indholdsudgivelse.`,
  gz = `Tilknyt synlig udgivelsesbegivenhed`,
  _z = `Vælg en synlig eksisterende begivenhed under grundspillet, som beskriver udgivelsen. Den vil kunne ses fra DLC-siden for sæsonpasset.`,
