  Tz = `Kommer:`,
  Ez = `Tilknytning mangler`,
  Dz = `Milepælen er allerede udgivet. Det er stadig muligt at tilknytte DLC eller en udgivelsesbegivenhed. Dette opdaterer blot visningen uden at ændre milepælens udgivelsesdato.`,
  Oz = `Tilknytning efter udgivelse af milepæl`,
  kz = `Milepælen er allerede markeret som udgivet til kunden. Dette kan bruges til at tilknytte manglende DLC og/eller en udgivelsesbegivenhed. Dette opdaterer blot visningen, når det udgives.`,
  Az = `Spørgeskema om møde med Steam-teamet`,
  jz = `Hej %1$s,%2$s Hvor vil du gerne møde os?`,
  Mz = `Nedenfor vises begivenheder, som Steam-teamet overvejer at deltage i. Hvis du også overvejer at deltage, eller du bor i nærheden og gerne vil mødes med os, så giv os besked i formularen nedenfor. Vi bruger disse oplysninger til vores rejse- og programplanlægning. Hvis du tilmelder dig en begivenhed, som vi planlægger at deltage i, vil vi prioriterer dem, som deltager i begivenheden, før vi sender flere invitationer ud.`,
  Nz = `Om dig`,
  Pz = `Fortæl os, hvem du er, og hvordan vi kan få fat i dig:`,
  Fz = `E-mail`,
  Iz = `Adresse mangler`,
  Lz = `Opdater e-mailadresse?`,
  Rz = `Dette er som standard den e-mailadresse, vi har i systemet for din partnerkonto. Du kan opdatere den, hvis du ønsker, at kommunikation om begivenheder sendes til en anden adresse.`,
  zz = `Virksomhed`,
  Bz = `Hvor skal du hen?`,
  Vz = `Fortæl os, hvilke spilbegivenheder du overvejer at deltage i i %1$s.`,
  Hz = `Angiver, hvilke begivenheder Steam-teamet planlægger at deltage i. Alle andre overvejer vi stadig.`,
  Uz = `Markér alle begivenheder, som du planlægger at deltage i, også selvom det ikke er bekræftet endnu.`,
  Wz = `Hvilke andre begivenheder, ud over dem ovenfor, planlægger du at deltage i?`,
  Gz = `Spørgeskemaet om konferencer er i øjeblikket lukket.`,
  Kz = `Har vi mødt dig personligt?`,
  qz = `Nej, jeg har aldrig personligt mødt et medlem af Steam-teamet`,
  Jz = `Føler du dig tryg ved at deltage i et foredrag eller en begivenhed, som primært eller udelukkende er på engelsk?`,
  Yz = `Ja, det er okay for mig, at engelsk er det primære sprog.`,
  Xz = `Nej, jeg har brug for hjælp til oversættelse.`,
  Zz = `Hvilket sprog foretrækker du?`,
  Qz = `Dette er for at hjælpe os med at vurdere, om der er behov for tolke under begivenheden`,
  $z = `Spørgeskema om Meet Steam: %1$s`,
  eB = `Har du feedback om nogen af de Steam-sessioner, du deltog i på Valves stand i Convene? Dette spørgeskema har bogstaveligt talt kun ét spørgsmål. Vi vil bare gerne vide, om der var noget, som sprang i øjnene med hensyn til indhold, kvalitet, timing, sted eller emne i sessionerne – uanset om det er godt eller dårligt.`,
  tB = `Tidligere begivenheder: (%1$s)`,
  nB = `Konferencearrangørerne vil gerne vide, om du planlægger at deltage, og om du er interesseret i at mødes med Steam-teamet.`,
  rB = `Andre konferencer`,
  iB = `Vælg bundt, som skal fastgøres`,
  aB = `Ingen fastgjorte bundter.`,
  oB = `Ingen valgmuligheder`,
  sB = `Træk ovenstående påkrævede assets hertil (maks. 50 MB).`,
  cB = `Enten er størrelsen forkert, eller filtypen understøttes ikke.`,
  lB = `%1$s er en dublet. Fjern det asset, du ikke vil fortsætte med.`,
  uB = `Der opstod et problem med at uploade denne fil. Prøv igen.`,
  dB = `Påkrævet asset mangler.`,
  fB = `Opstartsvideo`,
  pB = `Billedeksempel`,
  mB = `Retningslinjer for video`,
  hB = `Opstartsvideoer skal være 1920 px x 1200 px for at blive vist i fuld skærm på Steam Deck. De bør laves med omtanke omkring det faktum, at de bliver beskåret til 1920 px x 1080 px på de fleste skærme i Big Picture-tilstand.`,
  gB = `De bør være 3-10 sekunder lange.`,
  _B = `De må gerne inkludere dit spils logo, men de må ikke indeholde anden tekst eller markedsføringsmaterialer.`,
  vB = `Ingen gennemsigtighed tilladt. Du skal muligvis slå alfakanalen fra under eksport.`,
  yB = `Den endelige fil skal være i formatet .webm eller .mp4 og må ikke være større end 50 MB. Den komprimeres til en rimelig filstørrelse.`,
  bB = `Retningslinjer for lyd`,
  xB = `Alle opstartsvideoer indeholder lyd såvel som video. Lyden bør være designet til at komplimentere de små højtalere i Steam Decken, og den bør ikke være for høj, så den overvælder brugeren ved opstart.`,
  SB = `Lydfiler bør være i 16-bit 48 kHz-format.`,
  CB = `Det endelige lydoutput bør være -12 dB på det højeste og have en gennemsnitlig lydstyrke på -14 LUFS. Vi normaliserer lyden, så den ikke er for høj.`,
  wB = `Undgå for mange lav- og mellemfrekvenser, og overvej et HPF (high-pass filter), som starter på omkring 40-80 Hz.`,
  TB = `Overvej at tilføje lydudtoning i starten og slutningen af lydfilen for at undgå kliklyde eller skarpe klipninger til sidst i opstartsvideoen.`,
  EB = `Retningslinjer for billedeksempel`,
  DB = `Angiv et stillbillede på 1920 x 1200 px fra opstartsvideoen. Dette billede bruges til at repræsentere opstartsvideoen i brugerens inventar.`,
  OB = `JPEG, PNG og WebP accepteres.`,
  kB = `Ingen gennemsigtighed tilladt.`,
  AB = `Ingen animation tilladt. Billedet skal være en enkelt frame.`,
  jB = `Tilknyttet %1$s`,
  MB = `Dette navn kan ikke ændres, så længe det er tilknyttet en skaberside. Fjern først tilknytningen, hvis du vil redigere det.`,
  NB = `Fjern tilknytningen mellem "%1$s" og "%2$s" for dette spil. Dette træder i kraft med det samme.`,
  PB = `* Kræver, at du gemmer`,
  FB = `Din franchiseside kan ikke være den samme som din udvikler- eller udgiverside.`,
  IB = `Denne gruppe er allerede tilknyttet en udgiver med et andet navn. Se instruktionerne til højre.`,
  LB = `Denne gruppe er tilknyttet som udvikler eller udgiver på en anden app, så butikken viser den ikke som en franchise. Tilknyt i stedet en gruppe, som kun bruges til franchisen.`,
  RB = `Tilknyttet som udvikler eller udgiver på:`,
  zB = `(%1$s flere)`,
  BB = `Butikken knytter en franchise til skabersiden, når mindst to spil i butikken har den tilknyttet som deres franchise. DLC, demoer og software tæller ikke. Indtil da vises franchisenavnet uden en tilknytning.`,
  VB = `Vælg en skaberside`,
  HB = `Tilknyt "%1$s" til en side`,
  UB = `Vælg en eksisterende skaberside eller fællesskabsgruppe, som skal tilknyttes "'%1$s" for dette spil.`,
  WB = `Dette er en eksisterende skaberside, som er tilknyttet et andet spil for denne partnerkonto.`,
  GB = `* indikerer, at denne skaberside allerede er tilknyttet et andet spil under partnerkontoen.`,
  KB = `Partnerkontoen for dette spil kunne ikke fastlægges, så skabersider, som er tilknyttet dine andre spil, vises ikke her. Kun fællesskabsgrupper, som du ejer eller er officer i, vises.`,
  qB = `Der er ingen skaberside eller fællesskabsgruppe til tilknytning. Du skal være ejer af eller officer i fællesskabsgruppen, eller gruppen skal i forvejen være tilknyttet et andet spil for partnerkontoen.`,
  JB = `Listen over skabersider kunne ikke indlæses. Prøv igen senere.`,
  YB = `Link til skaberside fungerer ikke`,
  XB = `De følgende links til skabersiden findes i vores database, men de matcher ikke nogen af navnene ovenfor. Du kan trygt fjerne dem.`,
  ZB = `Strengen "%1$s" er tilknyttet skaberen %2$s`,
