  nV = `Tilknytningshistorikken kunne ikke indlæses. Prøv igen senere.`,
  rV = `Du har ikke tilladelse til at se tilknytningshistorikken for denne app.`,
  iV = `Der er ikke tilknyttet noget udvikler-, udgiver- eller franchisenavn til en skaberside for denne app endnu.`,
